-- INSERT preguntas PIR 2022 (convocatoria FSE 2022, Psicología)
-- Fuente: Cuaderno_2022_P_0_C.pdf + Plantilla_Respuestas_FSE_NuevasCapturas.xlsx
-- Generado: 204 preguntas validas de 210 impresas (6 anuladas excluidas: 22, 65, 87, 118, 143, 198)
-- especialidad/tema quedan NULL: se clasificaran en un paso posterior.

BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.preguntas WHERE "año" = 2022) THEN
    RAISE EXCEPTION 'Ya existen preguntas del año 2022 en la tabla preguntas — abortando para evitar duplicados.';
  END IF;
END $$;


COMMIT;

