INSERT INTO public.preguntas
  ("año", numero, especialidad, pregunta, opcion_a, opcion_b, opcion_c, opcion_d, opcion_e, correcta, imagen_path, tema)
VALUES
  (2022, 1, NULL, '¿Cuál de las siguientes es una condición para que pueda aplicarse el estadístico Chi cuadrado de independencia en una tabla de contingencia?:', 'Igual número de filas que de columnas.', 'Marginales de fila iguales a los marginales de columna.', 'Todos los residuales son 0.', 'No más del 20% de las frecuencias esperadas son menores a 5.', NULL, 'd', NULL, NULL),
  (2022, 2, NULL, 'El tamaño de la caja central de un diagrama de caja (Box Plot) viene dado por:', 'La amplitud intercuartílica.', 'El rango.', 'La desviación típica.', 'La diferencia entre media y mediana.', NULL, 'a', NULL, NULL),
  (2022, 3, NULL, '¿Qué estadístico emplearemos si queremos conocer la relación lineal entre las variables X e Y eliminando el efecto que una tercera variable (Z) tiene sobre Y?:', 'Covarianza.', 'Regresión.', 'Correlación semiparcial.', 'Correlación parcial.', NULL, 'c', NULL, NULL),
  (2022, 4, NULL, 'El diseño conocido como test de anclaje o ítems de anclaje es uno de los empleados en los procesos de:', 'Equiparación.', 'Baremación.', 'Validez de contenido.', 'Fiabilidad interjueces.', NULL, 'a', NULL, NULL),
  (2022, 5, NULL, 'Con el fin de probar el efecto de un factor, siendo el diseño no equilibrado y ante el incumplimiento del supuesto de homocedasticidad, la prueba adecuada es:', 'F de Levene.', 'Durbin-Watson.', 'W de Welch.', 'Fmáxima de Hartley.', NULL, 'c', NULL, NULL),
  (2022, 6, NULL, 'En un diseño multigrupos al azar, si el investigador desea realizar comparaciones a posteriori entre todos los pares de medias, en el caso de cumplimiento de los supuestos del modelo estadístico y para garantizar la mayor potencia y control del error de tipo I, la prueba más adecuada es:', 'El procedimiento de Bonferroni.', 'Prueba HSD de Tukey.', 'Prueba de Dunnet.', 'Prueba de Fisher.', NULL, 'b', NULL, NULL),
  (2022, 7, NULL, 'En el ámbito de las medidas del tamaño del efecto, para evaluar el impacto de un determinado tratamiento, indique cuál de las siguientes afirmaciones es correcta:', 'Eta cuadrado es equivalente al coeficiente de determinación de un modelo de regresión.', 'Omega cuadrado es un estimador sesgado por el tamaño muestral y se recomienda utilizar eta cuadrado en su lugar.', 'Delta de Cliff es un estimador paramétrico del tamaño del efecto.', 'Sólo la “d” de Cohen puede informar acerca del tamaño de efecto de un tratamiento.', NULL, 'a', NULL, NULL),
  (2022, 8, NULL, 'De acuerdo con la teoría de los lemmas de Levelt (1989) sobre la estructura interna de las palabras de nuestro léxico, ¿qué tipo de información, entre otras, contiene el lemma de una palabra?:', 'La morfología de la palabra.', 'La fonología de la palabra.', 'La ortografía de la palabra.', 'La sintaxis de la palabra.', NULL, 'd', NULL, NULL),
  (2022, 9, NULL, 'En el campo de estudio de la memoria semántica, ¿qué procedimiento experimental utilizaron Collins y Quillian (1969) para someter a contraste empírico su modelo de red jerárquica?:', 'Tarea de asociación de palabras.', 'Tarea de verificación de frases.', 'Tarea de denominación (naming).', 'Tarea de categorización semántica.', NULL, 'b', NULL, NULL),
  (2022, 10, NULL, 'En el contexto del estudio sobre el razonamiento silogístico, ¿cómo se denomina la hipótesis, planteada por Woodworth y Sells (1935), que propone que cuando un sujeto elabora una conclusión lo hace en función de la impresión global producida por las premisas?:', 'Efecto de la figura.', 'Efecto atmósfera.', 'Efecto de anclaje.', 'Efecto de la conjunción.', NULL, 'b', NULL, NULL),
  (2022, 11, NULL, '¿Qué función matemática utiliza S. S. Stevens (1957) para enunciar su ley psicofísica, derivada de los resultados obtenidos con métodos psicofísicos directos?:', 'La potencia.', 'El logaritmo.', 'La integral.', 'La raíz cuadrada.', NULL, 'a', NULL, NULL),
  (2022, 12, NULL, 'De acuerdo con la hipótesis de los niveles de procesamiento de Craik y Lockhart (1972), ¿qué tipo de repaso o repetición del material estudiado genera un mejor recuerdo de la información a largo plazo?:', 'El repaso de mantenimiento.', 'El repaso significativo.', 'El repaso elaborativo.', 'El repaso declarativo.', NULL, 'c', NULL, NULL),
  (2022, 13, NULL, 'En el marco del estudio del “motivo de afiliación”, McAdams (1980) intentó resaltar las experiencias positivas que permiten aumentar la calidad y armonía de las relaciones interpersonales; en este sentido se centró en el denominado:', 'Motivo de apego.', 'Motivo de vinculación emocional.', 'Motivo de empatía.', 'Motivo de intimidad.', NULL, 'd', NULL, NULL),
  (2022, 14, NULL, 'En el campo de estudio del razonamiento condicional, se utiliza con frecuencia la tarea de selección de Wason (1966), que consiste en la presentación de unas tarjetas con diversos estímulos. ¿Cuántas tarjetas componen la tarea?:', 'Dos.', 'Tres.', 'Cuatro.', 'Cinco.', NULL, 'c', NULL, NULL),
  (2022, 15, NULL, 'Cuando los niños comienzan a hablar, en ocasiones usan una palabra para referirse a una familia de objetos parecidos (p. ej., llaman ‘coche’ a todos los vehículos con ruedas). Este fenómeno se denomina:', 'Extensión o sobreextensión.', 'Generalización sintáctica.', 'Habla telegráfica.', 'Palabras pivote.', NULL, 'a', NULL, NULL),
  (2022, 16, NULL, 'Entre los 12 y 18 meses de vida, los bebés, en lugar de repetir conductas que producen consecuencias agradables, experimentan con nuevas conductas para ver lo que sucede. Este tipo de acciones se denominan:', 'Adaptación.', 'Asimilación.', 'Reacciones circulares secundarias.', 'Reacciones circulares terciarias.', NULL, 'd', NULL, NULL),
  (2022, 17, NULL, 'A la capacidad, desarrollada especialmente en la edad escolar, de evaluar una tarea cognitiva para determinar la mejor manera de realizarla y de controlar y supervisar su ejecución, se le denomina:', 'Acomodación.', 'Andamiaje.', 'Metacognición.', 'Periodo operacional concreto.', NULL, 'c', NULL, NULL),
  (2022, 18, NULL, 'Si cuando ponemos a un bebé ante la técnica de laboratorio de la situación extraña vemos que no llora cuando es separado de su cuidador principal y no busca su contacto cuando regresa, su apego es del tipo:', 'Desorganizado.', 'Ambivalente.', 'Seguro.', 'Evasivo.', NULL, 'd', NULL, NULL),
  (2022, 19, NULL, 'Señale cómo se denomina la teoría que plantea que, a lo largo de la vida, las personas estamos rodeadas de círculos concéntricos de relaciones de mayor o menor grado de cercanía de los que emana el apoyo social en las transiciones vitales, las crisis, etc.:', 'La constancia socioemocional.', 'El amortiguador (o buffer) social.', 'La caravana (o convoy) social.', 'La teoría del ciclo vital.', NULL, 'c', NULL, NULL),
  (2022, 20, NULL, 'De acuerdo con E. Erikson, el reto evolutivo típico que se plantea a las personas en la adultez emergente es el siguiente:', 'Intimidad frente a aislamiento.', 'Generatividad frente a estancamiento.', 'Productividad frente a desesperanza.', 'Orientación al presente frente a orientación al futuro.', NULL, 'a', NULL, NULL),
  (2022, 21, NULL, 'Cuando ante un dilema moral la persona enfatiza los principios y valores éticos universales, asumiendo incluso los costes personales que pudiera tener su decisión, nos encontramos ante un razonamiento moral:', 'Heterocéntrico.', 'Posconvencional.', 'Convencional.', 'Posformal.', NULL, 'b', NULL, NULL),
  (2022, 23, NULL, 'Señale en cuál de los siguientes modelos de regulación emocional se proponen tres componentes básicos, a saber, autocompasión, autoestímulo y autoinstrucción activa, para logar el autoapoyo efectivo:', 'Modelo de regulación emocional de Gross (1998, 2011).', 'Modelo de afrontamiento adaptativo de las emociones de Berking y Whitley (2014).', 'Modelo de regulación emocional basado en el procesamiento emocional de Hervás (2011).', 'El modelo de terapia dialéctica-conductual de Linehan (1993).', NULL, 'b', NULL, NULL),
  (2022, 24, NULL, 'Señale cuáles son las cuatro etapas del modelo ampliado de regulación emocional de Gross (2015):', 'Identificación, selección, implementación y monitorización.', 'Conciencia, identificación y etiquetación, identificación de factores causales y mantenedores, y modificación activa de emociones.', 'Identificación, aceptación, afrontamiento y autoapoyo.', 'Apertura emocional, aceptación emocional, análisis emocional y modulación emocional.', NULL, 'a', NULL, NULL),
  (2022, 25, NULL, 'Respecto del trastorno facticio (DSM-5), señale la opción FALSA:', 'Los individuos con trastorno facticio impuesto a uno mismo o impuesto a otro corren el riesgo de experimentar un gran sufrimiento psicológico o deterioro funcional.', 'Entre los pacientes hospitalarios, se estima que alrededor del 1% puede tener presentaciones que cumplan los criterios de trastorno facticio.', 'Por lo que se refiere al curso del trastorno, la presentación más frecuente es en forma de episodios intermitentes.', 'Su inicio suele ser en la adolescencia.', NULL, 'd', NULL, NULL),
  (2022, 26, NULL, 'Señale la opción FALSA respecto de la anorexia nerviosa (AN) (DSM-5):', 'La prevalencia a los 12 meses de la AN entre las mujeres jóvenes es aproximadamente del 0,4%.', 'La mayoría de los individuos con AN presenta una remisión a los 5 años del comienzo.', 'Los niveles de tiroxina (T4) en el suero están normalmente altos.', 'El hallazgo más sobresaliente en la exploración física es la emaciación.', NULL, 'c', NULL, NULL),
  (2022, 27, NULL, 'Señale la opción correcta respecto de los menores que presentan trastorno del apego reactivo (DSM-5):', 'Suelen buscar consuelo cuando sienten malestar, pero de forma peculiar.', 'Los episodios de irritabilidad, tristeza o miedo no son evidentes.', 'Tienen la capacidad de crear apegos selectivos.', 'Expresan emociones positivas de manera adecuada a sus figuras de apego.', NULL, 'c', NULL, NULL),
  (2022, 28, NULL, 'Los criterios diagnósticos del trastorno de estrés postraumático para niños mayores de 6 años (DSM-5) constan de una de las configuraciones sintomáticas siguientes:', 'Uno o más síntomas de intrusión, uno o más síntomas de evitación o alteración cognitiva y del estado de ánimo y dos o más síntomas de reactividad o alerta.', 'Uno o más síntomas de intrusión, uno o más síntomas de evitación, dos o más síntomas de alteraciones de la cognición y del estado de ánimo, y dos o más alteraciones de reactividad o alerta.', 'Uno o más síntomas de intrusión, uno o más síntomas de evitación, uno o más síntomas de alteración cognitiva y del estado de ánimo y dos o más síntomas de reactividad o alerta.', 'Uno o más síntomas de intrusión, uno o más síntomas de evitación, uno o más síntomas de alteración cognitiva y del estado de ánimo, y uno o más síntomas de reactividad o alerta.', NULL, 'b', NULL, NULL),
  (2022, 29, NULL, 'Señale cuál de las siguientes opciones NO hace referencia a una similitud entre la CIE-11 y el DSM-5 para el caso del autismo:', 'Ambos manuales hacen referencia al autismo aludiendo al término “espectro autista”.', 'Ambos manuales lo incluyen en los trastornos del neurodesarrollo.', 'Ambos manuales incluyen 3 niveles para clasificar la gravedad del trastorno.', 'Ambos manuales incluyen, como criterios nucleares, las dificultades para la comunicación e interacción social recíproca y los patrones restrictivos, repetitivos e inflexibles de comportamiento, intereses o actividades.', NULL, 'c', NULL, NULL),
  (2022, 30, NULL, 'Señale qué trastorno NO pertenece a la categoría de los trastornos del neurodesarrollo según la CIE-11:', 'Trastorno por déficit de atención/hiperactividad.', 'Trastorno de conducta disruptiva.', 'Trastorno por movimientos estereotipados.', 'Trastorno del desarrollo de la coordinación motora.', NULL, 'b', NULL, NULL),
  (2022, 31, NULL, 'Señale qué alteración formal del pensamiento presenta un paciente que muestra un discurso muy indirecto para contestar a las preguntas que se le formulan, aunque finalmente acaba contestando. Cuando explica algo aporta muchos detalles irrelevantes (pero con alguna relación con el tema principal), tediosos y, a veces, hace comentarios entre paréntesis excesivos:', 'Pérdida de meta.', 'Circunstancialidad.', 'Habla distraída.', 'Descarrilamiento.', NULL, 'b', NULL, NULL),
  (2022, 32, NULL, '¿Bajo qué tipo de delirio se engloban las experiencias de lectura del pensamiento, transmisión del pensamiento, robo del pensamiento y alienación del pensamiento?:', 'Delirio de suplantación.', 'Delirio de referencia o alusión.', 'Delirio de control o pasividad.', 'Delirio de persecución.', NULL, 'c', NULL, NULL),
  (2022, 33, NULL, 'El fenómeno de kindling (sensibilización) en la depresión se refiere a que:', 'Cada episodio sucesivo depresivo parece cada vez más dependiente del anterior y menos ligado a factores estresantes.', 'Cada episodio sucesivo depresivo parece cada vez más dependiente del anterior y más ligado a factores estresantes.', 'Cada vez son necesarios más estresores para provocar reapariciones de episodios depresivos en personas con sesgos cognitivos no tratados.', 'Cantidades cada vez más pequeñas de estresores pueden disparar reacciones de una intensidad comparable a los anteriores episodios.', NULL, 'd', NULL, NULL),
  (2022, 34, NULL, '¿Qué caracteriza a la preocupación patológica (o worry)?:', 'Se experimenta como una autoafirmación negativa, autodespreciativa, automática, plausible y breve, que no se relaciona con la búsqueda de soluciones.', 'Se experimenta como una cadena de pensamientos e imágenes, cargada de afecto negativo y relativamente incontrolable, que representa un intento improductivo de resolución mental de problemas futuros.', 'Se experimenta como una cadena de pensamientos centrada de forma repetitiva y pasiva en los síntomas de malestar emocional, así como en sus posibles causas y consecuencias, y cuyo contenido también puede estar centrado en acontecimientos negativos del pasado.', 'Son creencias anómalas y extrañas que se mantienen con una convicción elevada.', NULL, 'b', NULL, NULL),
  (2022, 35, NULL, 'Señale cuál de las siguientes opciones hace referencia a una característica diferenciadora de los trastornos depresivos y los trastornos bipolares:', 'El tratamiento con antidepresivos tricíclicos es más eficaz en trastornos bipolares que en depresivos.', 'Los antecedentes de varias generaciones con trastornos anímicos son más frecuentes en los trastornos bipolares que en los depresivos.', 'Las quejas somáticas son más frecuentes en los trastornos bipolares que en los depresivos.', 'Los episodios depresivos en el periparto son más comunes en los trastornos depresivos que en los bipolares.', NULL, 'b', NULL, NULL),
  (2022, 36, NULL, 'Señale la opción correcta respecto de los especificadores diagnósticos del trastorno de depresión mayor (DSM-5):', 'En remisión total: implica ausencia de síntomas significativos del trastorno en los últimos 3 meses.', 'Con características psicóticas: indica la presencia de alucinaciones y/o delirios congruentes siempre con el estado de ánimo.', 'Grave: puede emplearse en casos en los que se produce una interferencia notable en el funcionamiento social u ocupacional, entre otros criterios necesarios.', 'Con características mixtas: supone la presencia de síntomas de ansiedad la mayoría de los días.', NULL, 'c', NULL, NULL),
  (2022, 37, NULL, 'Respecto de la Teoría de Redes (TR) sobre el diagnóstico en depresión, señale la opción correcta:', 'Concibe los problemas psicológicos como elementos emergentes de un trastorno o enfermedad latente.', 'Considera que los síntomas y sus retroalimentaciones dinámicas son en sí mismos el problema y no una entidad latente.', 'Mantiene la idea de los sistemas politéticos de clasificación, tales como el DSM y la CIE.', 'La comorbilidad es entendida como la existencia de una serie de entidades esenciales que conectan dos tipos de redes de síntomas.', NULL, 'b', NULL, NULL),
  (2022, 38, NULL, 'Según el DSM-5, ¿qué presentación NO se incluye en la categoría de otro trastorno bipolar y trastorno relacionado especificado?:', 'Depresión con hipomanía mixta.', 'Episodio hipomaníaco sin episodio previo de depresión mayor.', 'Ciclotimia de corta duración.', 'Episodios hipomaníacos de corta duración (23 días) y episodios de depresión.', NULL, 'a', NULL, NULL),
  (2022, 39, NULL, 'Señale cuál de las siguientes opciones hace referencia a una característica diferencial entre depresiones unipolares y trastornos bipolares:', 'La duración de los episodios depresivos es mayor en el trastorno bipolar.', 'Los síntomas atípicos son más frecuentes en el trastorno bipolar.', 'La edad de inicio es mayor en el trastorno bipolar.', 'El retraso psicomotor es menos frecuente en el trastorno bipolar.', NULL, 'b', NULL, NULL),
  (2022, 40, NULL, 'Respecto del trastorno ciclotímico (DSM-5), señale la afirmación correcta:', 'Durante un periodo de dos años, los síntomas no han estado presentes durante más de tres meses seguidos.', 'Se deben cumplir los criterios para episodio depresivo, maníaco o hipomaníaco.', 'En población general, el trastorno ciclotímico es más frecuente en mujeres que en hombres.', 'En los niños, la edad promedio de inicio del trastorno son los 6 años y medio.', NULL, 'd', NULL, NULL),
  (2022, 41, NULL, 'Según el grupo de Öst, y respecto de los trastornos fóbicos:', 'La adquisición se produce, sobre todo, por condicionamiento o experiencia directa.', 'La adquisición se produce, sobre todo, por aprendizaje vicario.', 'La adquisición se produce, sobre todo, por transmisión de información de tipo negativo.', 'Las personas no pueden recordar el origen de su fobia.', NULL, 'a', NULL, NULL),
  (2022, 42, NULL, 'Según el grupo de trabajo sobre cogniciones obsesivas compulsivas (OCCWG, 1997, 2005), ¿cuál de las siguientes NO es una creencia disfuncional propia del trastorno obsesivo-compulsivo?:', 'Sobrevaloración de la importancia del pensamiento.', 'Responsabilidad exagerada.', 'Intolerancia a la incertidumbre.', 'Pensamiento dicotómico.', NULL, 'd', NULL, NULL),
  (2022, 43, NULL, 'Según el DSM-5, el trastorno de acumulación:', 'Se considera un especificador del trastorno obsesivo-compulsivo de la personalidad.', 'Requiere necesariamente la adquisición excesiva de cosas que no se necesitan o para las que no se dispone de espacio.', 'La acumulación es motivada por el deterioro cognitivo.', 'Requiere necesariamente que exista dificultad persistente para deshacerse o renunciar a las posesiones.', NULL, 'd', NULL, NULL),
  (2022, 44, NULL, '¿Cuáles de los siguientes síntomas aparecen entre los requeridos para la definición de un ataque de pánico según criterios DSM-5?:', 'Temblor o sacudidas y gritos o llanto incontrolables.', 'Parestesias y dolor de cabeza.', 'Escalofríos o sensación de calor y miedo a perder el control o a volverse loco.', 'Tensión muscular y sensación de dificultad para respirar o asfixia.', NULL, 'c', NULL, NULL),
  (2022, 45, NULL, '¿Cuál de los siguientes NO es un criterio para el diagnóstico del trastorno de ansiedad social según el DSM-5?:', 'La persona reconoce que el miedo es excesivo o irracional.', 'El miedo o la ansiedad son desproporcionados a la amenaza real planteada por la situación social y el contexto sociocultural.', 'El miedo, la ansiedad o la evitación son persistentes y duran típicamente seis o más meses.', 'El individuo tiene miedo de actuar de cierta manera o de mostrar síntomas de ansiedad que se valoren negativamente.', NULL, 'a', NULL, NULL),
  (2022, 46, NULL, 'Según los modelos cognitivos que explican la adquisición y mantenimiento de las fobias (p. ej., los modelos de Reiss), ¿cuál de los siguientes aspectos ocupa un papel central?:', 'La autofocalización de la atención.', 'La intolerancia a la incertidumbre y a la activación fisiológica.', 'Las expectativas de peligro y de ansiedad.', 'Las metacogniciones.', NULL, 'c', NULL, NULL),
  (2022, 47, NULL, '¿Cuál de los siguientes síntomas se incluye entre los requeridos para el diagnóstico de trastorno de ansiedad generalizada según el DSM-5?:', 'Sensación de pérdida de control.', 'Palpitaciones.', 'Dolor o molestias en el tórax.', 'Irritabilidad.', NULL, 'd', NULL, NULL),
  (2022, 48, NULL, 'En el marco de los trastornos parafílicos (DSM-5), señale la opción FALSA:', 'Se mantiene la categoría diagnóstica de fetichismo travestista.', 'El trastorno de fetichismo incluye el parcialismo.', 'El trastorno masoquista sexual tiene la asfixiofilia como posible especificador.', 'El trastorno de travestismo tiene el fetichismo como posible especificador.', NULL, 'a', NULL, NULL),
  (2022, 49, NULL, 'En cuanto a la clasificación de las disfunciones sexuales en el DSM-5, señale la opción FALSA:', 'Desaparece la etiqueta de trastorno por aversión al sexo como categoría independiente.', 'Engloba los problemas relacionados con la repuesta sexual o con el dolor asociado a la actividad sexual bajo la categoría de disfunciones sexuales.', 'Los problemas relacionados con la reducción o ausencia del interés/excitación/deseo sexual se abordan en 2 categorías diferentes, una para el caso femenino y otra para el masculino.', 'Desaparece la categoría de disfunción sexual inducida por sustancias/medicamentos.', NULL, 'd', NULL, NULL),
  (2022, 50, NULL, 'Según la CIE-11, ¿cuál de los siguientes diagnósticos NO se incluye en el capítulo 17 bajo la denominación de Condiciones relacionadas con la salud sexual?:', 'Discordancia de género.', 'Trastornos parafílicos.', 'Disfunciones sexuales.', 'Trastornos sexuales por dolor.', NULL, 'b', NULL, NULL),
  (2022, 51, NULL, 'Comparativamente con la esquizofrenia, ¿cuál de estas afirmaciones NO es cierta respecto al trastorno esquizofreniforme?:', 'El inicio es más rápido.', 'El inicio suele tener una fase prodrómica muy breve.', 'Hay una mayor convicción, extensión y presión de las ideas.', 'Los síntomas negativos son menores.', NULL, 'c', NULL, NULL),
  (2022, 52, NULL, '¿Cuál de estas afirmaciones NO es cierta con respecto a la fase residual de la esquizofrenia?:', 'Se produce una predominancia de los síntomas positivos frente a los negativos.', 'En ocasiones quedan síntomas positivos, pero acompañados de crítica.', 'La dimensión afectiva puede tener una importante presencia.', 'Se estima hasta un 80% de probabilidades de recaída en los cinco primeros años del primer episodio.', NULL, 'a', NULL, NULL),
  (2022, 53, NULL, '¿Cuál NO es una de las principales aseveraciones del modelo de Zubin para la esquizofrenia?:', 'Ninguna de las variables postuladas por los modelos parciales es necesaria ni suficiente para explicar el trastorno.', 'La esquizofrenia no es el cuadro tan maligno, persistente y deteriorante que se pensaba.', 'El trastorno tiene un curso crónico.', 'Si pudiéramos identificar marcadores de vulnerabilidad e intervenir sobre ellos, prevendríamos los episodios iniciales y los recurrentes.', NULL, 'c', NULL, NULL),
  (2022, 54, NULL, '¿Cuál es una característica principal que debe estar presente en la variante logopénica de la afasia primaria progresiva?:', 'Errores fonológicos en habla espontánea y nominación.', 'Alteración de la capacidad de denominar objetos.', 'Ausencia de agramatismo puro.', 'Deterioro en repetición de expresiones y frases.', NULL, 'd', NULL, NULL),
  (2022, 55, NULL, '¿Qué demencias comparten la pérdida de neuronas dopaminérgicas (área tegmental) y colinérgicas (prosencéfalo basal)?:', 'Demencia tipo enfermedad de Hungtinton y demencia asociada a la enfermedad de Parkinson.', 'Demencia vascular y demencia asociada a la enfermedad de Hungtinton.', 'Demencia por cuerpos de Lewy y demencia asociada a la enfermedad de Parkinson.', 'Demencia vascular y demencia por cuerpos de Lewy.', NULL, 'c', NULL, NULL),
  (2022, 56, NULL, '¿En qué tipo de demencia resulta más definitorio el deterioro de las funciones ejecutivas (perseverancia, desinhibición, desorganización y dificultad en la toma de decisiones), procesamiento enlentecido y déficits relacionados con la atención?:', 'Demencia tipo enfermedad de Hungtinton.', 'Parálisis supranuclear progresiva.', 'Demencia frontotemporal.', 'Enfermedad de Pick.', NULL, 'a', NULL, NULL),
  (2022, 57, NULL, '¿Cuál sería una de las causas adquiridas potencialmente reversibles en las demencias?:', 'Atrofia olivo-ponto-cerebelosa.', 'Enfermedad tiroidea.', 'Enfermedad de Binswanger.', 'Enfermedad priónica familiar.', NULL, 'b', NULL, NULL),
  (2022, 58, NULL, 'La propuesta alternativa de la sección III del DSM-5 para los trastornos de la personalidad incluye la valoración dentro del funcionamiento interpersonal (criterio A) de:', 'La empatía y la intimidad.', 'El autoconcepto y la autodirección.', 'Las relaciones interpersonales y la desregulación emocional.', 'La identidad y la autodirección.', NULL, 'a', NULL, NULL),
  (2022, 59, NULL, 'La sustancia que en el caso de empezar a consumirla antes de los 16 años parece incrementar el riesgo de padecer tumor de testículos en varones es:', 'La cocaína.', 'El LSD.', 'El alcohol.', 'El cannabis.', NULL, 'd', NULL, NULL),
  (2022, 60, NULL, 'Respecto del trastorno de pica (DSM-5), señale la opción correcta:', 'Se observa el consumo persistente de sustancias no nutritivas aunque sean alimentarias.', 'Se recomienda una edad mínima de 1 año para su diagnóstico.', 'Las sustancias normalmente ingeridas tienden a variar con la edad y la disponibilidad de las mismas.', 'La incidencia es muy superior en varones.', NULL, 'c', NULL, NULL),
  (2022, 61, NULL, '¿Cuál de las siguientes NO es una especificación indicada en el diagnóstico del trastorno específico del aprendizaje, según el DSM-5, en cuanto al área académica o subaptitud afectada?:', 'Con dificultades en la lectura.', 'Con dificultad en la expresión escrita.', 'Con dificultad matemática.', 'Con dificultad en la expresión oral.', NULL, 'd', NULL, NULL),
  (2022, 62, NULL, 'Según la CIE-11, en la anorexia nerviosa el punto de corte del Índice de Masa Corporal para determinar un peso corporal significativamente bajo es:', 'En adultos, inferior a 18,5; en niños (IMC para la edad), por debajo del percentil 7.', 'En adultos, inferior a 17,5; en niños (IMC para la edad), por debajo del percentil 8.', 'En adultos, inferior a 18,5; en niños (IMC para la edad), por debajo del percentil 5.', 'En adultos, inferior a 18; en niños (IMC para la edad), por debajo del percentil 5.', NULL, 'c', NULL, NULL),
  (2022, 63, NULL, 'En el modelo jerárquico de disociación de van der Hart, van der Kolk y Boon (1996), ¿qué implica la disociación primaria?:', 'El procesamiento fragmentado del acontecimiento traumático.', 'Percibir el acontecimiento sin experimentar un impacto emocional completo.', 'El desarrollo de identidades separadas.', 'Percibir el acontecimiento experimentando un impacto emocional completo.', NULL, 'a', NULL, NULL),
  (2022, 64, NULL, 'De acuerdo con la teoría de Kihlstrom para los trastornos disociativos, estos son considerados trastornos de:', 'La identidad.', 'La memoria.', 'La integración.', 'La representación.', NULL, 'b', NULL, NULL),
  (2022, 66, NULL, 'Desde el modelo del condicionamiento, por lo que se refiere a las víctimas de agresiones sexuales, ¿cuál de las siguientes afirmaciones es correcta?:', 'Las víctimas están más temerosas y ansiosas que las no víctimas.', 'La exposición repetida a la agresión sexual disminuiría la magnitud del miedo.', 'La ansiedad anticipatoria no propicia la evitación de situaciones lúdicas.', 'Las situaciones ansiógenas se relacionan con estímulos incondicionados a la violación.', NULL, 'a', NULL, NULL),
  (2022, 67, NULL, 'En el síndrome de las piernas inquietas:', 'Se produce malestar en las piernas y ocasionalmente en los brazos o el tronco, afectando negativamente a la capacidad para dormir.', 'El empeoramiento nocturno de los síntomas es dependiente de la fatiga durante el día.', 'Los síntomas se exacerban cuando el paciente está en continuo movimiento.', 'Los pacientes evitan el movimiento como vía de alivio o eliminación de los síntomas.', NULL, 'a', NULL, NULL),
  (2022, 68, NULL, 'Según el informe sobre el consumo de drogas que elabora la Oficina sobre Drogas y Crimen de Naciones Unidas (2016), ¿cuál es la ratio de personas entre 16 y 64 años que han consumido al menos una droga ilegal en el último año?:', 'Una de cada 20 de esas personas.', 'Una de cada 50 de esas personas.', 'Una de cada 100 de esas personas.', 'Una de cada 200 de esas personas.', NULL, 'a', NULL, NULL),
  (2022, 69, NULL, '¿Cuál de las siguientes características es FALSA para la desrealización?:', 'Es una experiencia subjetiva que implica cambio, extrañeza o irrealidad con respecto al entorno y al mundo que rodea a la persona.', 'La persona tiene la convicción firme delirante de que el entorno ha cambiado de un modo sutil, pero inquietante y difícil de definir, y está convencida de que está involucrada personalmente en tales cambios.', 'Puede aparecer en los mismos trastornos mentales que la despersonalización, así como en las mismas situaciones dentro de la población general.', 'Se considera una reacción disociativa en la que la persona experimenta una pérdida subjetiva de la experiencia de la realidad.', NULL, 'b', NULL, NULL),
  (2022, 70, NULL, 'Según el DSM-5, ¿qué nombre recibe el descriptor general de síntomas negativos característicos de la esquizofrenia que hace referencia a la pobreza del habla y pobreza del contenido del habla?:', 'Pararrespuesta.', 'Alogia.', 'Ilogicidad.', 'Mutismo selectivo.', NULL, 'b', NULL, NULL),
  (2022, 71, NULL, '¿Cómo se denomina el sentimiento exagerado y/o desproporcionado de bienestar, en el que la persona se siente llena de energía, alegre y optimista, que puede ocurrir en el transcurso de un episodio maníaco o hipomaníaco?:', 'Paratimia.', 'Elación.', 'Labilidad.', 'Hiperarousal.', NULL, 'b', NULL, NULL),
  (2022, 72, NULL, 'De acuerdo con el modelo etiológico multifactorial de Vanderlinden y Vandereycken (1997) formulado para explicar la relación entre experiencias traumáticas y síntomas disociativos, ¿qué factor favorece la ocurrencia de síntomas disociativos?:', 'Una mayor edad de la víctima.', 'Una estrecha relación entre atacante y víctima.', 'Una autoimagen negativa.', 'Un nivel intelectual bajo.', NULL, 'c', NULL, NULL),
  (2022, 73, NULL, 'Señale la respuesta FALSA, en cuanto a las variables, que desde una perspectiva transdiagnóstica, se han postulado como comunes en la predicción y el mantenimiento de la somatización y de la hipocondría (trastorno por síntomas somáticos y trastorno de ansiedad por la enfermedad en el DSM-5):', 'Los somatizadores e hipocondríacos suelen hacer con mayor probabilidad una atribución psicológica de los síntomas que las personas aquejadas de otros problemas psicológicos.', 'Se ha observado que sobrevalorar la importancia de los pensamientos relacionados con la salud y las enfermedades juega un papel importante en estos trastornos.', 'En los casos más extremos de estos problemas, se habla de fusión entre pensamiento y acción de tipo probabilidad.', 'La amplificación somatosensorial se ha planteado como una dimensión presente en estos trastornos.', NULL, 'a', NULL, NULL),
  (2022, 74, NULL, '¿Cuál de los siguientes factores cognitivos NO corresponde a los propuestos por Salkovskis y Warwick (1986, 2001) para explicar la hipocondría?:', 'Las creencias disfuncionales sobre el pensamiento repetitivo de enfermedad.', 'Percibir como terribles las consecuencias de sufrir una enfermedad (p.ej., perder el rol de madre o el trabajo).', 'El grado en que la persona se considera capaz de interferir en el curso de la enfermedad.', 'La valoración de la posibilidad de contar con factores externos que puedan intervenir en el caso de necesitar ayuda (p.ej., acceso a los servicios de salud).', NULL, 'a', NULL, NULL),
  (2022, 75, NULL, '¿Cuál de los siguientes módulos de tratamiento NO corresponde a la terapia cognitivo-conductual afectiva para la somatización de Woolfolk y Allen (2006)?:', 'Estimulación/regulación cognitivo emocional.', 'Entrenamiento en habilidades interpersonales y disminuir el rol de enfermo.', 'Exposición a situaciones temidas y a pensamientos e imágenes sobre la enfermedad.', 'Entrenamiento en habilidades conductuales.', NULL, 'c', NULL, NULL),
  (2022, 76, NULL, 'En cuanto al diagnóstico diferencial para el trastorno de síntomas neurológicos funcionales (TSNF) en el DSM-5, señale la respuesta correcta:', 'El TSNF no puede coexistir con una enfermedad neurológica.', 'Si se dan criterios para el trastorno de síntomas somáticos y para el trastorno de TSNF, deben realizarse ambos diagnósticos.', 'Respecto al trastorno facticio y la simulación, el diagnóstico de TSNF requiere que se demuestre que los síntomas no son fingidos.', 'Si un paciente presenta síntomas primarios de depresión, como tristeza y anhedonia, con quejas de pesadez general de sus miembros, se debe hacer el diagnóstico de TSNF.', NULL, 'b', NULL, NULL),
  (2022, 77, NULL, 'Una persona que presenta síntomas somáticos leves, con un grado elevado de ansiedad asociado y comportamientos excesivos relacionados con la salud, con la certeza absoluta desde hace más de 6 meses de que padece una enfermedad grave, con una gran fijación y persistencia a pesar de las evidencias en contra, y con una disminución de la capacidad para reconocer que la creencia es consecuencia de un trastorno mental, padece con más probabilidad:', 'Trastorno de conversión.', 'Trastorno por síntomas somáticos.', 'Trastorno delirante de tipo somático.', 'Trastorno de ansiedad por la enfermedad.', NULL, 'c', NULL, NULL),
  (2022, 78, NULL, 'Según el DSM-5, que un niño tenga una comprensión muy limitada de la comunicación simbólica en el habla y la gestualidad y dependa de otros para todos los aspectos del cuidado físico diario, la salud y la seguridad, es característico de una discapacidad intelectual de gravedad:', 'Leve.', 'Moderado.', 'Grave.', 'Profundo.', NULL, 'd', NULL, NULL),
  (2022, 79, NULL, 'Señalar la asociación correcta entre sistema modulador difuso, origen en el tronco encefálico y función en la que se halla implicado:', 'Noradrenérgico – Locus coeruleus – control conducta emocional.', 'Serotoninérgico – complejo pontomesencefálicocontrol del estado de ánimo.', 'Dopaminérgico – área tegmental ventral – sistema de recompensa y conductas adaptativas.', 'Colinérgico – núcleos del rafe – participación en el aprendizaje y la formación de recuerdos.', NULL, 'c', NULL, NULL),
  (2022, 80, NULL, '¿En cuál de estas áreas corticales una lesión produce prosopagnosia?:', 'Giro lingual.', 'Giro frontal inferior.', 'Giro fusiforme.', 'Giro postcentral.', NULL, 'c', NULL, NULL),
  (2022, 81, NULL, 'Los cuerpos celulares del circuito dopaminérgico mesolímbico tienen su origen en:', 'El núcleo arqueado.', 'El núcleo paraventricular.', 'El área tegmental ventral.', 'Los núcleos del rafe.', NULL, 'c', NULL, NULL),
  (2022, 82, NULL, 'Supongamos que la frecuencia dominante en un electroencefalograma es en un determinado momento 30Hz. ¿En cuál de estas situaciones es más probable que se encuentre la persona a quien se lo estamos registrando?:', 'Realizando este examen.', 'Relajada y con los ojos cerrados, aunque despierta.', 'En la fase 2 del sueño.', 'En la fase 4 del sueño.', NULL, 'a', NULL, NULL),
  (2022, 83, NULL, '¿Cuál de estas estructuras cerebrales se ha asociado en mayor medida con la familiaridad mnésica?:', 'Cuerpos mamilares.', 'Núcleo anterior del tálamo.', 'Corteza perirrinal.', 'Cuerno de Amón (campos CA1, CA2, CA3).', NULL, 'c', NULL, NULL),
  (2022, 84, NULL, '¿Con cuál de los siguientes procesos lingüísticos se asocia en mayor medida el componente N400 de los potenciales evocados cerebrales?:', 'Procesamiento semántico.', 'Procesamiento sintáctico.', 'Procesamiento prosódico.', 'Procesamiento perceptivo (detección del símbolo lingüístico).', NULL, 'a', NULL, NULL),
  (2022, 85, NULL, 'Señale la respuesta correcta en relación a los mecanismos neurobiológicos del sueño:', 'Las neuronas noradrenérgicas y serotoninérgicas con origen en el tronco encefálico son las responsables del apagado del sueño REM.', 'El neurotransmisor melatonina se libera sólo en condiciones de oscuridad y ayuda a iniciar y mantener el sueño.', 'La adenosina es un factor promotor del sueño mediante su efecto activador sobre los sistemas moduladores difusos del tronco.', 'Durante el sueño se produce una alta expresión de genes inmediatos tempranos y mitocondriales en consonancia con los requerimientos metabólicos.', NULL, 'a', NULL, NULL),
  (2022, 86, NULL, 'Señale cuál de las siguientes opciones es correcta con relación al control cerebral del movimiento:', 'La hipercinesia presente en el balismo se produce por una disfunción en el área motora suplementaria.', 'Los fascículos vestibuloespinales potencian los reflejos antigravitatorios de la médula espinal.', 'Una lesión en la parte superior del sistema motor genera de inmediato hipertonía, arreflexia y espasticidad.', 'El fascículo tectoespinal genera la respuesta orientada que dirige el movimiento de la cabeza y de los ojos a un estímulo.', NULL, 'd', NULL, NULL),
  (2022, 88, NULL, 'Señale cuál de las siguientes afirmaciones sobre la relación entre distintas áreas cerebrales y distintos aspectos de la cognición social es correcta:', 'En la capacidad de “leer” la mente de los demás participan la corteza prefrontal medial y la unión temporoparietal.', 'Las principales áreas cerebrales implicadas en la empatía son la corteza cingulada anterior y la prefrontal.', 'Las áreas cerebrales principalmente responsables de la primera impresión son el área de Broca y la amígdala.', 'Las neuronas espejo se localizan en la corteza temporal superior y su actividad muestra poca capacidad de aprendizaje.', NULL, 'a', NULL, NULL),
  (2022, 89, NULL, '¿Qué dos tipos de sexismo contempla la teoría del sexismo ambivalente?:', 'Homófobo y heterófobo.', 'Hostil y benevolente.', 'Manifiesto e implícito.', 'Aversivo y sutil.', NULL, 'b', NULL, NULL),
  (2022, 90, NULL, '¿Cuáles son los dos componentes fundamentales del modelo de racismo simbólico o moderno?:', 'Afecto negativo y apoyo a los valores de la ética protestante.', 'Estereotipos negativos y discriminación pasiva.', 'Prejuicio implícito y socialización positiva.', 'Activación automática y procesamiento consciente.', NULL, 'a', NULL, NULL),
  (2022, 91, NULL, 'Según el modelo de covariación de Kelley, cuando una conducta muestra consenso alto, distintividad alta y consistencia alta, su causa se atribuye a:', 'El estímulo.', 'La personalidad del sujeto.', 'La situación/circunstancia.', 'El estado emocional del sujeto.', NULL, 'a', NULL, NULL),
  (2022, 92, NULL, '¿Cuál de las siguientes afirmaciones sobre el modelo MODE (motivación y oportunidad como determinantes de la relación actitud-conducta) de Fazio (1990) es correcta?:', 'Integra los conceptos de norma subjetiva y objetiva.', 'Es un modelo de enfoque expectativa-valor.', 'Es un modelo trifactorial.', 'Integra los conceptos de procesamiento espontáneo y elaborado.', NULL, 'd', NULL, NULL),
  (2022, 93, NULL, 'En el modelo de socialización grupal propuesto por Levine y Moreland, ¿qué dos procesos están involucrados en la denominada fase de investigación?:', 'Acomodación y asimilación.', 'Reclutamiento y reconocimiento.', 'Tradición y remembranza.', 'Exploración y verificación.', NULL, 'b', NULL, NULL),
  (2022, 94, NULL, '¿Cuál de las siguientes opciones recoge una de las dimensiones del Cuestionario de Ambiente Grupal elaborado por Carron y colaboradores?:', 'Similitud percibida intragrupal.', 'Categorización grupal compartida.', 'Relaciones comunes en el grupo.', 'Atracción individual hacia la tarea del grupo.', NULL, 'd', NULL, NULL),
  (2022, 95, NULL, '¿Cuál de los siguientes procesos fue evidenciado mediante el paradigma experimental denominado “azul-verde” aplicado por Moscovici y colaboradores?:', 'Conversión.', 'Metacontraste.', 'Reactancia.', 'Inferencia correspondiente.', NULL, 'a', NULL, NULL),
  (2022, 96, NULL, 'Las actividades o hábitos de vida que reducen el riesgo de morbilidad y muerte prematura, en terminología de Matarazzo (1984), se denominan:', 'Inmunógenos conductuales.', 'Patógenos conductuales.', 'Condiciones de vida.', 'Prevención terciaria.', NULL, 'a', NULL, NULL),
  (2022, 97, NULL, 'Las tres creencias básicas de la teoría de la acción planeada de Ajzen (1988) son el control conductual percibido, la norma subjetiva y:', 'La actitud hacia la conducta específica.', 'El apoyo social.', 'El sentido de coherencia.', 'La discriminación del riesgo.', NULL, 'a', NULL, NULL),
  (2022, 98, NULL, 'Además de McCrae y Costa, de los siguientes autores ¿quiénes proponen modelos de personalidad de 5 factores?:', 'Tupes y Christal.', 'Cattell.', 'Eysenck.', 'Ashton.', NULL, 'a', NULL, NULL),
  (2022, 99, NULL, 'El modelo de estructura del intelecto propuesto inicialmente por Guilford postula existencia de:', 'Un total de 15 (5+4+6) aptitudes de inteligencia.', 'Un total de 120 (5x4x6) aptitudes de inteligencia.', 'Tres aptitudes de inteligencia (general, de grupo y específica).', 'Tres aptitudes de inteligencia (analítica, práctica y creativa).', NULL, 'b', NULL, NULL),
  (2022, 100, NULL, 'Desde el modelo atribucional de Weiner, ¿qué tres dimensiones se contemplan?:', 'Distintividad, consistencia y consenso.', 'Estabilidad, globalidad e internalidad.', 'Intencionalidad, estabilidad y especificidad.', 'Locus de causalidad, estabilidad y controlabilidad.', NULL, 'd', NULL, NULL),
  (2022, 101, NULL, 'Desde la teoría componencial de Sternberg, el autor destaca los siguientes componentes para la adquisición del conocimiento:', 'Reconocimiento, monitorización y comprensión.', 'Codificación, inferencia y aplicación.', 'Codificación selectiva, combinación selectiva y comparación selectiva.', 'Inferencia, selección y decisión selectiva.', NULL, 'c', NULL, NULL),
  (2022, 102, NULL, 'Respecto a las teorías implícitas de personalidad, señala la alternativa correcta:', 'Algunas personas consideran que los atributos personales pueden cambiarse, es decir, poseen una teoría implícita de entidad.', 'Las teorías implícitas, como creencias que son, no están sujetas a influencias ni pueden cambiar.', 'Algunas personas consideran que los atributos personales se poseen en una cantidad fija y no pueden cambiarse, es decir, poseen una teoría implícita incremental.', 'Algunas personas consideran que los atributos personales se poseen en una cantidad fija y no pueden cambiarse, es decir, poseen una teoría implícita de entidad.', NULL, 'd', NULL, NULL),
  (2022, 103, NULL, '¿Qué autores proponen un modelo en el que se ensalza la relevancia tanto del sistema cognitivo-afectivo de la personalidad como de las características psicológicas de la situación a la hora de explicar la conducta humana?:', 'A. Bandura.', 'W. Mischel e Y. Shoda.', 'H. Eysenck y M. Eysenck.', 'J. Gray.', NULL, 'b', NULL, NULL),
  (2022, 104, NULL, '¿Cuál de los siguientes modelos surge con el objetivo de identificar las bases biológicas que subyacen a la inteligencia?:', 'Modelo de la integración parieto-occipital de la inteligencia.', 'Modelo de la integración frontal-parietal de la inteligencia.', 'Modelo de la integración temporo-parietal de la inteligencia.', 'Modelo de la integración frontal-temporal de la inteligencia.', NULL, 'b', NULL, NULL),
  (2022, 105, NULL, 'De entre los siguientes tipos de pruebas, ¿en cuáles se evalúa la creatividad mediante las puntuaciones en fluidez, flexibilidad y originalidad de las respuestas de los participantes?:', 'Test de pensamiento divergente.', 'Test de pensamiento convergente.', 'Inventarios de juicios de productos.', 'Inventarios de actitudes e intereses.', NULL, 'a', NULL, NULL),
  (2022, 106, NULL, '¿Qué dimensiones de personalidad del modelo de cinco factores de Costa y McCrae se relacionan con el factor general de psicopatología o factor p?:', 'Neuroticismo, apertura a la experiencia y extraversión.', 'Neuroticismo, responsabilidad y amabilidad/cordialidad.', 'Neuroticismo, responsabilidad y apertura a la experiencia.', 'Neuroticismo, extraversión y amabilidad/cordialidad.', NULL, 'b', NULL, NULL),
  (2022, 107, NULL, '¿Quién fue el introductor del concepto de cociente intelectual?:', 'William Stern.', 'James McKeen Catell.', 'Alfred Binet.', 'Louis Terman.', NULL, 'a', NULL, NULL),
  (2022, 108, NULL, 'Cuando comparamos modelos clásicos de personalidad, como el PEN, con el modelo de los cinco grandes, podemos observar:', 'La correspondencia entre un mayor psicoticismo y una menor cordialidad y responsabilidad.', 'La correspondencia entre un mayor psicoticismo y una mayor cordialidad y responsabilidad.', 'La correspondencia entre un menor psicoticismo y una menor cordialidad y responsabilidad.', 'La correspondencia entre un mayor psicoticismo y una mayor cordialidad y menor responsabilidad.', NULL, 'a', NULL, NULL),
  (2022, 109, NULL, 'Señale qué dimensión del modelo de los cinco grandes recoge mejor la calidad de la interacción social:', 'Cordialidad.', 'Extraversión.', 'Estabilidad emocional.', 'Responsabilidad.', NULL, 'a', NULL, NULL),
  (2022, 110, NULL, 'Señale cuál de los siguientes instrumentos de evaluación de las alucinaciones incluye la evaluación de los patrones de afrontamiento (resistencia y compromiso):', 'Launay-Slade Hallucination Scale-revised (LSHS-R; Bentall y Slade, 1985; Fonseca-Pedrero et al., 2010).', 'Psychotic Symptom Rating Scale (PSY-RATS; Haddock et al., 1999; González et al., 2003).', 'Beliefs About Voice Questionnaire (BAVQ-R; Chadwick et al., 2000; Robles García et al., 2004).', 'Voice Power Differential Scale (VPDS; Birchwood et al., 2000).', NULL, 'c', NULL, NULL),
  (2022, 111, NULL, '¿Cuál de las siguientes decisiones NO pertenece al muestreo intersesional?:', 'Período de observación.', 'Número de sesiones de observación.', 'Criterios de inicio de sesión.', 'Intervalos en que se divide la sesión de observación.', NULL, 'd', NULL, NULL),
  (2022, 112, NULL, 'Entre las fuentes de error en la observación procedentes del sistema de observación se incluye:', 'Grado de entrenamiento para la observación.', 'Grado de participación en la observación.', 'Tipo de registro elegido para la observación.', 'Expectativas creadas para la observación.', NULL, 'c', NULL, NULL),
  (2022, 113, NULL, '¿Qué índice se obtiene en todas las escalas de inteligencia de Wechsler (WPSSI-IV, WISC-V y WAIS-IV)?:', 'Índice visoespacial.', 'Índice razonamiento perceptivo.', 'Índice memoria de trabajo.', 'Índice razonamiento fluido.', NULL, 'c', NULL, NULL),
  (2022, 114, NULL, '¿Cuál de las siguientes pruebas es una entrevista semiestructurada para evaluar el trastorno obsesivo compulsivo en la infancia y la adolescencia?:', 'Inventario de Obsesiones de Leyton, versión para niños (LOI-CV) de Berg y colaboradores.', 'Escala Yale –Brown de Obsesiones y Compulsiones para niños (CY-BOCS) de Scahill y colaboradores.', 'Inventario Obsesivo-Compulsivo de Maudsley (MOCI) de Hodgson y Rachman.', 'Inventario Obsesivo-Compulsivo para niños (CHOCI) de Shafran y colaboradores.', NULL, 'b', NULL, NULL),
  (2022, 115, NULL, '¿Qué indicación es apropiada para ajustar la entrevista a un escolar de 9 años?:', 'Utilizar preferentemente preguntas cerradas.', 'Evitar preguntas que empiecen con “¿por qué?”.', 'Recurrir a juegos no verbales (dibujos, juguetes, etc.).', 'Emplear alternativas de respuesta para reducir la probabilidad de sugestión.', NULL, 'b', NULL, NULL),
  (2022, 116, NULL, 'En el Test de Apercepción Temática para niños (CAT), ¿qué aspecto NO se tiene en cuenta para el análisis del contenido de las historias?:', 'Preferencias e identificaciones.', 'Conflictos significativos.', 'Figuras vistas como…', 'Naturaleza de la ansiedad.', NULL, 'a', NULL, NULL),
  (2022, 117, NULL, 'A diferencia del MMPI para adultos, en la versión para adolescentes:', 'Se han agregado áreas de contenido como el potencial agresivo.', 'Contiene 11 escalas clínicas, 5 para relaciones personales y 5 para el tratamiento.', 'Incluye escalas suplementarias para evaluar problemas de alcohol y drogas, y la inmadurez.', 'Se ha reducido a 300 el número de ítems.', NULL, 'c', NULL, NULL),
  (2022, 119, NULL, '¿Cuál de los siguientes cuestionarios para la evaluación de la depresión en la infancia cuenta con una forma abreviada?:', 'Escala de Depresión para Niños (CDS) de Lang y Tisher.', 'Cuestionario Educativo Clínico: Ansiedad y Depresión (CECAD) de Lozano y Colaboradores.', 'Inventario de Depresión Infantil (CDI) de Kovac.', 'Escala de Sintomatología Depresiva para Maestros de Educación Primaria (ESDM 612) de Domènech y Polaino.', NULL, 'c', NULL, NULL),
  (2022, 120, NULL, 'Dentro de las estrategias narrativas en evaluación psicológica, el análisis del proyecto vital (Mahoney):', 'Se focaliza directamente en la elaboración de un relato sobre la identidad personal.', 'Consta de tres fases: recomposición de la vida, viaje por la vida y revisar la revisión vital.', 'Se trata de una evaluación sin restricciones al texto, pero sin criterios hermenéuticos.', 'Utiliza categorías transitivas e intransitivas de afectos para el análisis de la revisión de vida.', NULL, 'c', NULL, NULL),
  (2022, 121, NULL, 'En la técnica de observación, ¿qué nombre reciben los productos de conducta procedentes de ejecuciones del sujeto en el pasado?:', 'Medidas retrospectivas.', 'Medidas prospectivas.', 'Medidas retroactivas.', 'Medidas no reactivas.', NULL, 'd', NULL, NULL),
  (2022, 122, NULL, 'Indique la respuesta correcta con respecto al pensamiento-en-voz-alta:', 'Es una técnica estructurada de autoinforme.', 'En el registro de eventos, el procedimiento más complejo es la categorización de contenido verbal.', 'La verbalización ocurre independientemente de la conducta informada.', 'Un procedimiento de recogida de los pensamientos es el monólogo continuo.', NULL, 'd', NULL, NULL),
  (2022, 123, NULL, '¿Cómo se denomina a la descripción que hace el entrevistador de lo que está ocurriendo en un determinado momento en cuanto a la relación entre el entrevistador y el entrevistado?:', 'Inmediatez.', 'Interpretación.', 'Encuadre.', 'Confrontación.', NULL, 'a', NULL, NULL),
  (2022, 124, NULL, 'Según la Guía de Proceso de Evaluación (GAP) (Fernández-Ballesteros y colaboradores, 2003), ¿en qué subfase el evaluador realiza la tarea de preparar la situación de evaluación y da instrucciones al sujeto?:', 'Operativización de las hipótesis mediante instrumentos y procedimientos de evaluación.', 'Análisis de las demandas, quejas, metas.', 'Recogida de información: recopilación de información pertinente.', 'Discusión y toma de decisiones.', NULL, 'c', NULL, NULL),
  (2022, 125, NULL, '¿Cuál de los siguientes instrumentos está dirigido a medir la disociación de movimientos entre ambas manos?:', 'Omega.', 'Rotor de persecución.', 'Test de punteado.', 'Tromómetro de barra.', NULL, 'a', NULL, NULL),
  (2022, 126, NULL, '¿Cuál de las siguientes pruebas corresponde al índice de velocidad de procesamiento en el Test de Inteligencia de Wechsler para Adultos (WAIS-IV)?:', 'Dígitos.', 'Búsqueda de símbolos.', 'Figuras incompletas.', 'Matrices.', NULL, 'b', NULL, NULL),
  (2022, 127, NULL, 'Respecto a las técnicas de registro de información observacionales, ¿qué son las escalas de apreciación?:', 'Son registros en los que el observador va realizando descripciones narrativas sobre lo observado en la conducta del sujeto.', 'Se usan para la cuantificación, calificación o clasificación de las actividades de un sujeto según específicas definiciones conductuales, dimensiones o atributos de personalidad previamente establecidos.', 'Son técnicas de observación sin estructuración previa, que suelen comenzar con una observación no sistemática para observar el continuo de la conducta de un sujeto.', 'Son técnicas de observación en las que se recoge la información en un breve período de tiempo.', NULL, 'b', NULL, NULL),
  (2022, 128, NULL, 'La teoría triárquica de Sternberg entiende la inteligencia en función de tres subteorías: la subteoría contextual, experiencial y componencial. ¿A qué hace referencia la subteoría experiencial?:', 'A la adaptación al medio.', 'A la habilidad para enfrentarse a situaciones novedosas.', 'A las estructuras y mecanismos que rigen el funcionamiento inteligente.', 'A la habilidad para entender el contexto sociocultural.', NULL, 'b', NULL, NULL),
  (2022, 129, NULL, 'Según la clasificación de Cronbach (1992), los tests de rendimiento típico, en comparación con los de rendimiento máximo, son aquellos que:', 'Recogen los niveles más altos de rendimiento de una persona.', 'Son técnicas involuntarias en las que la persona habitualmente no percibe el constructo que se está intentado evaluar.', 'Evalúan constructos como, por ejemplo, la personalidad o las actitudes.', 'Evalúan la cantidad de ítems bien resueltos por el sujeto en un tiempo determinado.', NULL, 'c', NULL, NULL),
  (2022, 130, NULL, 'Señale la afirmación correcta sobre el Test de Aptitudes Mentales Primarias (PMA):', 'Su edad de aplicación es a partir de los 10 años. Evalúa aptitudes verbales, espaciales, de razonamiento, numéricas y de fluidez verbal.', 'Su edad de aplicación es a partir de los 8 años. Evalúa comprensión verbal, numéricas y aptitud perceptiva.', 'Su edad de aplicación es a partir de los 7 años. Evalúa razonamiento numérico, verbal y abstracto.', 'Su edad de aplicación es a partir de los 9 años. Evalúa actitud verbal, razonamiento y espacial.', NULL, 'a', NULL, NULL),
  (2022, 131, NULL, '¿Qué afirmación es INCORRECTA con respecto a las características de las técnicas proyectivas?:', 'Se basan en que el sujeto evaluado cuenta con una estructura básica y estable de la personalidad.', 'Toda respuesta ante el material proyectivo no es casual, sino significativa, y será entendida como un signo de la personalidad del sujeto.', 'Cuanto más ambiguas sean las propiedades de los estímulos, tanto menos reflejarán la personalidad las respuestas de los sujetos.', 'El análisis de las respuestas de los sujetos ha de ser fundamentalmente cualitativo y global.', NULL, 'c', NULL, NULL),
  (2022, 132, NULL, 'En evaluación psicológica, ¿qué técnicas metódicas y objetivos de evaluación se ajustan al modelo de atributo?:', 'Estrategias de observación clínica y objetivos de clasificación.', 'Estrategias experimentales y objetivos de explicación de relaciones funcionales.', 'Estrategias correlacionales y objetivos de pseudoexplicación.', 'Estrategias observacionales y objetivos de descripción.', NULL, 'c', NULL, NULL),
  (2022, 133, NULL, 'Indique qué supuestos pueden formularse a la hora de establecer hipótesis en el proceso de evaluación psicológica (p. ej., Fernández Ballesteros):', 'Supuestos de cuantificación, supuestos de semejanza, supuestos de asociación predictiva y supuestos de asociación funcional.', 'Supuestos de semejanza, supuestos de asociación funcional, supuestos epistemológicos y supuestos cualitativos.', 'Supuestos de cuantificación, supuestos de axioma, supuestos de asociación predictiva y supuestos aleatorios.', 'Supuestos de asociación predictiva, supuestos de semejanza, supuestos de asociación funcional y supuestos idiográficos.', NULL, 'a', NULL, NULL),
  (2022, 134, NULL, 'En el psicograma de Rorschach, ¿qué tipo de respuestas se tienen en cuenta para el análisis de los afectos?:', 'Respuestas de Color.', 'Respuestas de Sombreado.', 'Respuestas de Claroscuro.', 'Respuestas de Figuras Humanas.', NULL, 'a', NULL, NULL),
  (2022, 135, NULL, 'De las siguientes técnicas estructurales derivadas de la teoría de los constructos personales de Kelly, ¿cuál ahonda en los significados más profundos del evaluado y en las emociones asociadas?:', 'Escalamiento.', 'Flujo de conciencia.', 'Flecha descendente.', 'Autocaracterización.', NULL, 'c', NULL, NULL),
  (2022, 136, NULL, '¿Qué representan los elementos en la administración de la técnica de rejilla interpersonal aplicada en el campo clínico?:', 'Las filas en el protocolo de la técnica de rejilla.', 'Las personas significativas de la vida del evaluado.', 'Las similitudes y diferencias entre los constructos.', 'El punto de saturación del evaluado.', NULL, 'b', NULL, NULL),
  (2022, 137, NULL, 'En la evaluación psicofisiológica, ¿cuáles de los siguientes indicadores biológicos NO identifican a las personas con mayor probabilidad de desarrollar un trastorno?:', 'Los marcadores de vulnerabilidad.', 'Los marcadores genéticos.', 'Los marcadores endofenotípicos.', 'Los marcadores episódicos.', NULL, 'd', NULL, NULL),
  (2022, 138, NULL, '¿Cuál de los siguientes factores cognitivos se ha relacionado con la conducta antisocial en niños y adolescentes?:', 'El centro de control interno.', 'La baja autoeficacia percibida.', 'La desesperanza.', 'El autoconcepto positivo.', NULL, 'b', NULL, NULL),
  (2022, 139, NULL, 'Según el DSM-5, el trastorno negativista desafiante:', 'Describe en una sola categoría el trastorno negativista desafiante como un patrón de enfado/irritabilidad, discusiones/actitud desafiante o vengativa.', 'Describe dos situaciones para el trastorno negativista desafiante en relación con el estado emocional que lo acompaña.', 'Describe el trastorno negativista desafiante como un patrón persistente de comportamientos que violan las normas y la reglas acompañado de un comportamiento de desafío hacia la autoridad.', 'Describe el trastorno negativista desafiante como arrebatos recurrentes en el comportamiento que reflejan una falta de control del impulso de agresividad.', NULL, 'a', NULL, NULL),
  (2022, 140, NULL, '¿Cuál de los siguientes tratamientos psicológicos va dirigido al trastorno de la personalidad límite?:', 'Diálogo Abierto.', 'Programa STEPPS.', 'Terapia interpersonal y del ritmo social.', 'Terapia familiar funcional.', NULL, 'b', NULL, NULL),
  (2022, 141, NULL, '¿Cuál de las siguientes afirmaciones es cierta en relación con la conducta agresiva en niños y adolescentes?:', 'El procedimiento tiempo fuera para eliminar comportamientos agresivos no es recomendable para niños menores de 10 años.', 'Los tratamientos conductuales para el tratamiento de la conducta agresiva son más eficaces con adolescentes que con niños.', 'Los niños con problemas de agresividad buscan más indicios que aquellos que no muestran problemas de agresividad, antes de determinar las intenciones de sus compañeros en situaciones sociales ambiguas.', 'Un modo de disminuir la probabilidad de ocurrencia del comportamiento agresivo en niños es reducir la estimulación aversiva de su contexto inmediato.', NULL, 'd', NULL, NULL),
  (2022, 142, NULL, 'Señale la respuesta correcta con respecto a los trastornos de personalidad:', 'La CIE-11 propone una clasificación categorial de los trastornos de personalidad.', 'El DSM-5 incluye los trastornos de personalidad en el eje II, dentro de su clasificación multiaxial.', 'El DSM-5 incluye una propuesta alternativa para la clasificación de los trastornos de personalidad en la sección III, donde asume un modelo híbrido de los trastornos de personalidad.', 'El DSM-5 difiere del DSM-IV al incluir 12 trastornos de personalidad, organizados en tres grupos.', NULL, 'c', NULL, NULL),
  (2022, 144, NULL, 'El instrumento ADOS-2 para la evaluación del autismo es:', 'Un Cuestionario de cribado para determinar posibles casos de niños que presentan señales de alerta de un TEA alrededor de los 18 meses.', 'Un Cuestionario de Comunicación Social, de respuesta si/no cumplimentado por los padres y que evalúa principalmente la interacción social.', 'Una entrevista estructurada revisada que evalúa la comunicación, la interacción social y la presencia de esterotipias e intereses restringidos.', 'Una escala de observación estandarizada y semiestructurada para el diagnóstico de autismo con varios módulos adaptados a cada grupo de edad y nivel de lenguaje.', NULL, 'd', NULL, NULL),
  (2022, 145, NULL, '¿Qué terapia se emplea para el tratamiento del trastorno límite de la personalidad en adolescentes?:', 'Terapia interpersonal adaptada para niños y adolescentes.', 'Terapia familiar orientada al apego.', 'Terapia dialéctico-conductual en formato grupal.', 'Terapia de desarrollo de habilidades familiares y psicoeducación.', NULL, 'c', NULL, NULL),
  (2022, 146, NULL, '¿Cuál de las siguientes afirmaciones es FALSA en relación con los tratamientos psicológicos de la discapacidad intelectual?:', 'Las terapias basadas en atención plena son una alternativa terapéutica aplicada también a las personas con discapacidad intelectual.', 'La terapia centrada en la compasión es un enfoque terapéutico contextualista que se ha aplicado en el ámbito de la discapacidad intelectual para el abordaje de la autocrítica y la comparación social negativa.', 'Al igual que en la población general, la depresión es el principal problema en el que se ha investigado la eficacia de la activación conductual aplicada a personas con discapacidad intelectual.', 'Varios ensayos aleatorios controlados han generado evidencias de calidad alta que confirman la efectividad de los modelos de terapia de tercera generación en el tratamiento de la discapacidad intelectual.', NULL, 'd', NULL, NULL),
  (2022, 147, NULL, '¿Cuál de las siguientes afirmaciones es FALSA en relación con los modelos de tratamiento psicológico del trastorno del desarrollo del lenguaje?:', 'Las aproximaciones más centradas en el niño (en contraposición a las más centradas en el terapeuta) hacen un uso amplio del modelado, el moldeamiento y el reforzamiento.', 'Los tratamientos más centrados en el terapeuta siguen una estructura básica de enseñanza que consiste en la presentación de un modelo lingüístico, la petición de su reproducción por el niño y el feedback.', 'Los enfoques más formales y focalizados de tratamiento se corresponden con las aproximaciones más centradas en el terapeuta.', 'Los enfoques naturales, que se corresponden con los centrados en el niño, emplean recursos comunicativos propios de las interacciones ordinarias de un modo más intencional.', NULL, 'a', NULL, NULL),
  (2022, 148, NULL, '¿Cuál de los siguientes tratamientos está dirigido al abordaje de los trastornos de conducta en niños y adolescentes?:', 'Terapia basada en el modelo de Worden.', 'El programa los años increíbles.', 'Intervención compresiva conductual.', 'El programa Coping Cat.', NULL, 'b', NULL, NULL),
  (2022, 149, NULL, 'Cuando un menor presenta fracaso constante para hablar en situaciones sociales específicas en las que existe expectativa por hablar, es característico de:', 'Trastorno del lenguaje.', 'Trastorno fonológico.', 'Mutismo selectivo.', 'Trastorno de la comunicación social.', NULL, 'c', NULL, NULL),
  (2022, 150, NULL, 'Señale cuál de los siguientes componentes NO pertenece a la terapia conductual para la esquizofrenia (Kingdom y Turkington, 2005):', 'Explicación normalizadora de la psicosis.', 'Examen de los antecedentes de la crisis psicótica.', 'Tratamiento de la ansiedad y depresión coexistentes.', 'Formulación de las conexiones entre A-B-C y el desarrollo psicológico evolutivo.', NULL, 'd', NULL, NULL),
  (2022, 151, NULL, 'De las siguientes características, ¿cuál NO corresponde al entrenamiento en escenificaciones emotivas para las fobias infantiles?:', 'Se utiliza en menores de 9 años.', 'Se caracteriza por suscitar emociones positivas.', 'Utiliza sistemas de refuerzo social.', 'Entrena en relajación muscular progresiva.', NULL, 'd', NULL, NULL),
  (2022, 152, NULL, '¿Cuál de los siguientes fármacos NO está indicado para el trastorno bipolar?:', 'Lamotrigina.', 'Flufenazina.', 'Oxcarbazepina.', 'Clordiazepóxido.', NULL, 'd', NULL, NULL),
  (2022, 153, NULL, '¿Cuál de los siguientes efectos secundarios es más frecuente en el tratamiento neuroléptico con aripiprazol en la esquizofrenia?:', 'Galactorrea.', 'Parkinsonismo.', 'Hipercolesterolemia.', 'Discinesia tardía.', NULL, 'c', NULL, NULL),
  (2022, 154, NULL, 'El modelo de autorregulación de Kanfer, en el que se apoya la terapia de autocontrol de Rhem para la depresión, señala déficits específicos en 3 fases diferentes. Señale cuáles:', 'La motivación, el tratamiento y la prevención de recaídas.', 'La conductual, cognitiva y experiencial.', 'La autoobservación, la autoevaluación y el autorreforzamiento.', 'La autocontemplación, la autoidentificación y la conciencia de enfermedad.', NULL, 'c', NULL, NULL),
  (2022, 155, NULL, 'Señale cuál de las siguientes terapias define específicamente que su foco de interés es la depresión y, más concretamente, la resolución de un problema de la vida del paciente relacionado con duelo complicado, transición o conflicto de roles, o problemas en las relaciones con los demás:', 'La terapia racional emotiva.', 'La terapia de aceptación y compromiso.', 'La terapia cognitiva.', 'La terapia interpersonal.', NULL, 'd', NULL, NULL),
  (2022, 156, NULL, 'En el ámbito de la terapia de conducta y por lo que respecta al curso de afrontamiento de la depresión (CAD; Lewinsohn y col.), señale la opción correcta:', 'El CAD se suele añadir a los programas de actividades agradables y al entrenamiento en habilidades sociales, pero se considera que la terapia cognitiva es innecesaria y hasta puede ser contraproducente.', 'En el CAD, el papel del terapeuta es poco directivo para que los participantes sean los conductores del grupo.', 'El CAD fue diseñado para adultos con depresión, pero se ha extendido a otras poblaciones y condiciones.', 'El CAD no cuenta con evidencia empírica sobre su eficacia.', NULL, 'c', NULL, NULL),
  (2022, 157, NULL, 'Con respecto a la terapia interpersonal (TIP; Weissman, Markowitz y Klerman, 2018), señale la respuesta correcta:', 'Es una terapia que no está determinada temporalmente (se pueden ir añadiendo sesiones hasta conseguir los objetivos terapéuticos).', 'Ofrece un marco comprensivo completo de la depresión, similar a otras terapias como la activación conductual o la terapia cognitiva.', 'Defiende que la depresión es una enfermedad y su aparición obedece a cambios en el entorno interpersonal como consecuencia de distintos problemas.', 'No da importancia al análisis del afecto o la emoción elicitados por las circunstancias.', NULL, 'c', NULL, NULL),
  (2022, 158, NULL, '¿Qué intervención psicológica para la depresión tiene como propia la técnica TRAP-TRAC(k) (Jacobson et al. 2001) que sirve de guía y motivación a la persona en tratamiento?:', 'Activación conductual.', 'Terapia dialéctico-conductual.', 'Terapia racional-emotiva.', 'Terapia interpersonal.', NULL, 'a', NULL, NULL),
  (2022, 159, NULL, '¿En qué consisten los tres bloques que integran el programa de entrenamiento en reconocimiento emocional (Wölwer et al, 2005)?:', 'El primer bloque está dirigido a identificar emociones básicas; el segundo a trabajar el procesamiento emocional; el tercero a la identificación de expresiones más ambiguas del afecto.', 'El primer bloque está dirigido a la diferenciación entre estímulos visuales sin componente social; el segundo a trabajar la identificación de emociones básicas; el tercero a trabajar el procesamiento emocional.', 'El primer bloque está dirigido a la identificación de expresiones ambiguas de afecto; el segundo a conocer los componentes de la cognición social; el tercero a trabajar la teoría de la mente.', 'El primer bloque está dirigido a entrenar habilidades sociales básicas; el segundo a entrenar habilidades sociales complejas; el tercero a trabajar el procesamiento emocional.', NULL, 'a', NULL, NULL),
  (2022, 160, NULL, '¿En qué consisten las tres fases que integran el programa entrenamiento en cognición social e interacción (Penn et al, 2005)?:', 'La primera aborda los déficits en cognición social más habituales en la psicosis; la segunda propone un entrenamiento en procesamiento emocional; la tercera consiste en un entrenamiento en teoría de la mente.', 'La primera propone un entrenamiento en funciones neurocognitivas básicas como atención, memoria y funciones ejecutivas; la segunda propone un entrenamiento en procesamiento emocional, teoría de la mente y estilo atribucional; la tercera consiste en un entrenamiento en metacognición.', 'La primera aborda las habilidades sociales básicas; la segunda trata de un entrenamiento en habilidades sociales complejas; la tercera va dirigida a la extrapolación de las habilidades aprendidas a la vida diaria.', 'La primera aborda la comprensión de emociones; la segunda se dirige al estilo de cognición social; la tercera va dirigida a la consolidación de habilidades aprendidas y extrapolación de las mismas a la vida diaria.', NULL, 'd', NULL, NULL),
  (2022, 161, NULL, '¿Cuál es la diferencia fundamental entre la terapia para la mejora cognitiva (CET) (Hogarty y Flesher, 1999) y el programa de terapia psicológica integrada para la esquizofrenia (IPT) (Roder y cols., 1996)?:', 'CET solo aborda aspectos relacionados con la neurocognición, mientras que IPT trabaja tanto en neurocognición como en cognición social.', 'IPT solo aborda aspectos relacionados con la neurocognición, mientras que CET trabaja tanto en neurocognición como en cognición social.', 'Aunque ambos abordan tanto déficits en cognición social como en neurocognición, IPT es menos lineal y escalonado que CET.', 'Aunque ambos abordan tanto déficits en cognición social como en habilidades cognitivas, CET es menos lineal y escalonado que IPT.', NULL, 'd', NULL, NULL),
  (2022, 162, NULL, '¿Qué cuatro habilidades, postuladas por Lysaker y Dimaggio (2014), suelen abordar los programas destinados a la mejora de la metacognición en psicosis?:', 'Autorreflexividad, comprensión de la mente del otro, teoría de la mente y estilo atribucional.', 'Procesamiento emocional, percepción/conocimiento social, teoría de la mente y estilo atribucional.', 'Autorreflexividad, comprensión de la mente del otro, descentramiento y capacidad para integrar la información intersubjetiva que permita resolver los problemas de forma adaptativa.', 'Percepción emocional, descentramiento, percepción/conocimiento social y estilo atribucional.', NULL, 'c', NULL, NULL),
  (2022, 163, NULL, '¿Qué tres funciones cognitivas básicas se trabajan mediante la terapia para la mejora cognitiva (CET) (Hogarty y Flesher, 1999)?:', 'Atención, velocidad de procesamiento y memoria de trabajo.', 'Atención, memoria y resolución de problemas.', 'Memoria, fluidez verbal y aprendizaje verbal.', 'Memoria, velocidad de procesamiento y praxias.', NULL, 'b', NULL, NULL),
  (2022, 164, NULL, 'Señale cuál de los siguientes trastornos del sueño es una disomnia:', 'Alteraciones circadianas.', 'Bruxismo.', 'Somniloquios.', 'Terrores nocturnos.', NULL, 'a', NULL, NULL),
  (2022, 165, NULL, 'En el marco de las intervenciones en la esquizofrenia y por lo que respecta al tratamiento focalizado en la familia (Miklowitz et al., 1988, 1996, 1997), señale la opción correcta:', 'Se basa en que el paciente crea estrés en la familia.', 'Se basa en que el paciente está influenciado por el estrés en su familia.', 'Se basa en disminuir las interacciones familiares.', 'Es un modelo no estructurado.', NULL, 'b', NULL, NULL),
  (2022, 166, NULL, 'En los problemas de erección, ¿qué técnica se emplea para evitar el rol de espectador eliminando la ansiedad de rendimiento?:', 'Autoestimulación.', 'Empleo de fantasías sexuales.', 'Alineación coital.', 'Técnica del puente.', NULL, 'b', NULL, NULL),
  (2022, 167, NULL, 'El tratamiento de un trastorno orgásmico femenino generalizado debe comenzar por:', 'Masturbación delante del compañero sexual.', 'Focalización sensorial.', 'Relaciones coitales.', 'Masturbación a solas.', NULL, 'd', NULL, NULL),
  (2022, 168, NULL, '¿En qué consiste la maniobra del puente?:', 'En simultanear la estimulación manual de los genitales con movimientos coitales hasta que se produzca la eyaculación intravaginal.', 'En eyacular fuera de la vagina.', 'En acariciarse mutuamente ambos miembros de la pareja hasta alcanzar el orgasmo simultáneo.', 'En masturbarse delante de la pareja.', NULL, 'a', NULL, NULL),
  (2022, 169, NULL, '¿Qué intervenciones en el tratamiento de las adicciones se definen por el establecimiento de medidas para que el consumo se produzca en condiciones de seguridad para la salud de los usuarios?:', 'Comunidades terapéuticas.', 'Centros de día.', 'Programas con antagonistas opiáceos.', 'Programas de reducción de daños.', NULL, 'd', NULL, NULL),
  (2022, 170, NULL, 'En el modelo de Marlatt y Gordon (1985), a las conductas, racionalizaciones y minimizaciones del riesgo que llevan a las personas a situaciones de alta probabilidad de consumo se las denomina:', 'Matriz adictiva de valoración.', 'Craving.', 'Decisiones aparentemente irrelevantes.', 'Creencias justificativas.', NULL, 'c', NULL, NULL),
  (2022, 171, NULL, '¿Con qué fin, en algunos programas de tratamiento del tabaquismo (p. ej., Becoña, 2007), se solicita a los sujetos que inicialmente reduzcan la cantidad de nicotina?:', 'Para reducir la probabilidad de síntomas de abstinencia.', 'Para controlar los estímulos.', 'Para obtener feedback fisiológico del consumo.', 'Para realizar un autorregistro del consumo.', NULL, 'a', NULL, NULL),
  (2022, 172, NULL, 'En el tratamiento cognitivo-conductual específico para la bulimia nerviosa de Fairburn, Marcus y Wilson (1993), ¿cuándo se recomienda introducir la reestructuración cognitiva?:', 'En la fase primera.', 'En la fase segunda.', 'En la fase tercera.', 'En la fase primera y tercera indistintamente, siempre que el paciente presente infrapeso severo.', NULL, 'b', NULL, NULL),
  (2022, 173, NULL, 'En el tratamiento de la anorexia nerviosa en adultos, ¿qué recomienda la guía NICE respecto a los programas de tratamiento cognitivo-conductual individual como tratamiento de elección de primera línea?:', 'Explicar los riesgos de la desnutrición y el bajo peso.', 'Generalmente consiste en hasta 20 sesiones.', 'Iniciar con posterioridad a la terapia farmacológica.', 'Aplicar como paso previo antes de abordar la rehabilitación nutricional.', NULL, 'a', NULL, NULL),
  (2022, 174, NULL, '¿En qué creencias se centra la terapia metacognitiva (Wells, 2009) para el trastorno obsesivo-compulsivo?:', 'En el contenido de las obsesiones y su vinculación con la historia personal del paciente.', 'En creencias acerca de los pensamientos y/o intrusiones, por ejemplo, en términos de fusión entre pensamientos, sucesos y acciones.', 'En las creencias metacognitivas relacionadas con la rumiación.', 'En las creencias positivas que la persona mantiene en torno a la preocupación.', NULL, 'b', NULL, NULL),
  (2022, 175, NULL, 'Señale la alternativa correcta en relación con la aplicación de la exposición con prevención de respuesta (EPR) en grupo para el trastorno obsesivo-compulsivo (TOC):', 'La EPR para el TOC no puede realizarse en grupo porque se trata de un trastorno heterogéneo.', 'Aunque es prometedor, en términos de coste-eficacia, no hay estudios sobre la eficacia de la modalidad grupal de la EPR.', 'Los estudios de metaanálisis han mostrado que no hay diferencias entre el formato de la EPR (individual o en grupo) en la eficacia de la intervención.', 'La EPR en grupo es menos eficaz que la aplicación individual y, además, hay más riesgo de abandonos.', NULL, 'c', NULL, NULL),
  (2022, 176, NULL, 'Un paciente con trastorno obsesivo-compulsivo realiza la siguiente afirmación sobre sus obsesiones y estrategias de control: “cuando me asalta la idea de tener relaciones sexuales inapropiadas, me digo ‘¡basta!’ e inmediatamente intento pensar en algo agradable”. Elige la indicación terapéutica correcta en este caso:', 'Reforzar la estrategia de control del paciente, ya que el entrenamiento le permitirá parar el pensamiento negativo.', 'Indicar al paciente que utilice esta estrategia de control con otros pensamientos disfuncionales para generalizar el aprendizaje.', 'Indicar al paciente que intente pensar en actividades sexuales apropiadas cuando le asalte el pensamiento negativo.', 'Ayudarle a identificar las estrategias de neutralización que utiliza en respuesta a las obsesiones.', NULL, 'd', NULL, NULL),
  (2022, 177, NULL, 'De entre las distintas intervenciones psicológicas para el tratamiento del trastorno de estrés postraumático, cuáles tienen nivel de evidencia 1, según las guías de evidencia clínica:', 'Búsqueda de seguridad, entrenamiento en inoculación del estrés y exposición prolongada.', 'Exposición prolongada, debriefing y EMDR.', 'EMDR, búsqueda de seguridad y exposición prolongada.', 'Exposición prolongada, terapia de procesamiento cognitivo y EMDR.', NULL, 'd', NULL, NULL),
  (2022, 178, NULL, 'En la terapia EMDR, la fase denominada desensibilización consiste en que:', 'Se chequea si existe alguna sensación negativa somática y si fuera el caso se completa el procesamiento.', 'Se trabaja con la estabilización y acceso a experiencias y emociones positivas.', 'Se pregunta por el recuerdo principal que está en la base del malestar actual.', 'Se provoca estimulación mediante movimientos oculares, escucha bilateral con un audio y/o estimulación táctil en manos, hombros y piernas (tapping).', NULL, 'd', NULL, NULL),
  (2022, 179, NULL, 'En el contexto del tratamiento del estrés postraumático, las técnicas de exposición, tanto en imaginación como en vivo, suponen que la aproximación a los recuerdos traumáticos o a las situaciones temidas conduce a (señale la INCORRECTA):', 'El procesamiento emocional de la información afectiva.', 'La habituación de la ansiedad.', 'La eliminación de información correctora.', 'La vivencia de dominio sobre la experiencia de que la ansiedad no implica pérdida de control.', NULL, 'c', NULL, NULL),
  (2022, 180, NULL, 'De entre las terapias para personas con trastorno de estrés postraumático y sentimientos de culpa asociados, ¿cuál incluye específicamente una narrativa escrita del trauma?:', 'La terapia centrada en el presente.', 'La terapia del procesamiento cognitivo.', 'El entrenamiento en inoculación del estrés.', 'La terapia EMDR.', NULL, 'b', NULL, NULL),
  (2022, 181, NULL, 'Señale la afirmación correcta sobre la técnica implosiva desarrollada por Stampfl y Levis (1967) para el tratamiento de los trastornos de ansiedad:', 'Se debe eliminar siempre la contingencia entre la respuesta y el estímulo condicionado.', 'Los estímulos aversivos no están asociados a contenidos dinámicos.', 'Uno de los objetivos de esta técnica es impedir cualquier respuesta de escape.', 'Esta técnica se suele aplicar tanto en imaginación como en vivo.', NULL, 'c', NULL, NULL),
  (2022, 182, NULL, 'Según el modelo de habituación dual enunciado por Watts (1979) para la comprensión del mantenimiento de las respuestas de ansiedad, señale la correcta:', 'La ausencia de respuesta de escape se debe a la existencia de una respuesta que competía con ella.', 'En la reducción de las respuestas de ansiedad intervienen simultáneamente dos procesos distintos, de sensibilización y de habituación.', 'En la reducción de las respuestas de ansiedad intervienen dos procesos distintos que se van alternando sin darse simultáneamente, de sensibilización y de habituación.', 'Si la frecuencia de la respuesta de evitación/escape se mantiene en 0, el resto de las respuestas de ansiedad nunca se extinguen.', NULL, 'b', NULL, NULL),
  (2022, 183, NULL, 'Respecto a las diferentes modalidades que se pueden utilizar al aplicar técnicas de exposición, señale las que obtienen una mayor eficacia:', 'Exposición con presencia del terapeuta y modalidad en imaginación.', 'Autoexposición y modalidad de exposición en vivo.', 'Psicofármacos antidepresivos y modalidad de exposición mediante realidad virtual.', 'Exposición con presencia del terapeuta y uso de psicofármacos ansiolíticos.', NULL, 'b', NULL, NULL),
  (2022, 184, NULL, 'Indique cuál de los siguientes procedimientos clínicos introdujo en primer lugar el mindfulness como parte de un tratamiento multicomponente:', 'Terapia de conducta dialéctica de Marsha Linehan.', 'Terapia cognitiva basada en mindfulness de la depresión.', 'Terapia de aceptación y compromiso.', 'Desensibilización sistemática.', NULL, 'a', NULL, NULL),
  (2022, 185, NULL, '¿Cuál de los siguientes enunciados define la creencia disfuncional de sobrestimar la importancia del pensamiento, en el caso del trastorno obsesivo-compulsivo?:', 'Otorgar un significado personal relevante y negativo a la ocurrencia de las obsesiones o de sus contenidos.', 'Sobrevalorar la importancia de ejercer un control completo sobre las obsesiones.', 'Creer que controlar las obsesiones es posible y deseable.', 'Pensar que uno tiene un poder decisivo para provocar o prevenir acontecimientos negativos.', NULL, 'a', NULL, NULL),
  (2022, 186, NULL, 'Con respecto a la adaptación de la terapia a las características de la persona, ¿cuál de las siguientes afirmaciones es correcta?:', 'Las personas con estilo de afrontamiento internalizante obtienen mejores resultados con tratamientos focalizados en la reducción de síntomas.', 'Las personas con alta reactancia obtienen mejores resultados con tratamientos en los que el enfoque del terapeuta es menos directivo.', 'Las personas con estilo de afrontamiento externalizante obtienen mejores resultados con tratamientos dirigidos a fomentar el insight y la autoconciencia.', 'Las personas con baja reactancia obtienen mejores resultados con tratamientos en los que el enfoque del terapeuta se basa en intervenciones paradójicas.', NULL, 'b', NULL, NULL),
  (2022, 187, NULL, 'El trazado de límites y el trabajo con la jerarquía familiar pertenecen a la escuela:', 'Estructural de Minuchin.', 'Estratégica de Haley.', 'Intergeneracional de Bowen.', 'Experiencial de Satir.', NULL, 'a', NULL, NULL),
  (2022, 188, NULL, '¿Cuáles son las técnicas de cambio que se utilizan en la terapia psicoanalítica?:', 'Análisis de la transferencia y contratransferencia e interpretación.', 'Interpretación, confrontación y clarificación.', 'Análisis de las resistencias y clarificación.', 'Asociación libre, atención flotante y confrontación.', NULL, 'b', NULL, NULL),
  (2022, 189, NULL, 'El programa de tratamiento de Clare Philips (1987/1991):', 'Se utiliza en pacientes con dolor crónico.', 'Se aplica a pacientes con trastorno bipolar.', 'Se utiliza en pacientes con ansiedad social.', 'Se aplica en régimen ambulatorio en pacientes con esquizofrenia.', NULL, 'a', NULL, NULL),
  (2022, 190, NULL, '¿Cuál de los siguientes factores de la relación terapéutica ha demostrado encontrarse dentro de la categoría de mayor nivel de eficacia?:', 'El uso de autorrevelaciones.', 'La promoción de la credibilidad del tratamiento.', 'El manejo de la contratransferencia.', 'La obtención y uso de feedback.', NULL, 'd', NULL, NULL),
  (2022, 191, NULL, '¿Cuál es la variable que mejor predice el resultado de una terapia psicológica (p. ej., Norcross y Lambert, 2019)?:', 'Las características del paciente.', 'Las técnicas específicas empleadas.', 'El modelo teórico del psicólogo.', 'Los factores comunes.', NULL, 'a', NULL, NULL),
  (2022, 192, NULL, '¿Cuál de las siguientes afirmaciones, relativas a la investigación en psicoterapia sobre la alianza terapéutica, es FALSA?:', 'La solidez de la alianza predice los resultados de la psicoterapia.', 'La relación entre alianza y resultados se produce en cualquier tipo de terapia estudiada.', 'La percepción de la calidad de la alianza por el terapeuta predice mejor el éxito o el fracaso de la terapia que la percepción del paciente.', 'La reparación de rupturas en la alianza favorece la relación terapéutica.', NULL, 'c', NULL, NULL),
  (2022, 193, NULL, '¿Cuál de las siguientes técnicas es característica de la terapia centrada en soluciones (Shazor y colaboradores)?:', 'Desesperanza creativa.', 'Tarea del tigre.', 'Técnica de la rejilla.', 'Búsqueda de excepciones.', NULL, 'd', NULL, NULL),
  (2022, 194, NULL, 'En el protocolo unificado para el tratamiento transdiagnóstico de los trastornos emocionales para adultos (Barlow y colaboradores), ¿qué variables se deben evaluar al realizar los ejercicios de exposición a las sensaciones físicas?:', 'Nivel de ansiedad y evitación.', 'Grado de dificultad y aversión.', 'Grado de malestar y similitud.', 'Nivel de dominio y agrado.', NULL, 'c', NULL, NULL),
  (2022, 195, NULL, 'En la terapia dialéctica-conductual las habilidades de tolerancia al malestar se dividen en habilidades de supervivencia a las crisis y:', 'Habilidades de atención plena.', 'Habilidades de regulación emocional.', 'Habilidades de eficacia interpersonal.', 'Habilidades de aceptación de la realidad.', NULL, 'd', NULL, NULL),
  (2022, 196, NULL, 'El concepto de difusión de identidad, dentro de los trastornos de personalidad, ha sido ampliamente desarrollado por:', 'Marsha Linehan.', 'Peter Fonagy.', 'Otto Kernberg.', 'Heinz Kohut.', NULL, 'c', NULL, NULL),
  (2022, 197, NULL, 'La terapia dialéctica-conductual para el trastorno límite de la personalidad (TLP) se basa en las siguientes teorías explicativas del TLP (Linehan, 1993):', 'La teoría del marco relacional y la teoría dialéctica.', 'La teoría del apego y la modificación de conducta.', 'La teoría de la mente y la teoría dialéctica.', 'La teoría dialéctica y la teoría biosocial.', NULL, 'd', NULL, NULL),
  (2022, 199, NULL, 'El modelo específico utilizado por la terapia cognitivo analítica para el tratamiento de los trastornos de la personalidad se conoce como:', 'Modelo dialógico del self.', 'Modelo de estados múltiples del self.', 'Teoría cognitiva del self.', 'Modelo del procedimiento secuenciado.', NULL, 'b', NULL, NULL),
  (2022, 200, NULL, 'Señale qué dimensiones son evaluadas cuando se realiza el “perfil mentalizador” de un paciente con un trastorno de personalidad desde la terapia basada en la mentalización (Fonagy y Bateman, 2016):', 'Automática versus controlada y cognitiva versus afectiva.', 'Automática versus controlada; otro versus uno mismo y cognitiva versus afectiva.', 'Automática versus controlada; otro versus uno mismo; interna versus externa y cognitiva versus afectiva.', 'Automática versus controlada; otro versus uno mismo; interna versus externa; cognitiva versus afectiva y social versus individual.', NULL, 'c', NULL, NULL),
  (2022, 201, NULL, 'La terapia focalizada en la transferencia define la organización borderline de la personalidad con los siguientes elementos:', 'Defensas primitivas, prueba de realidad mantenida y sólida identidad.', 'Defensas primitivas, fallo en la prueba de realidad y difusión de identidad.', 'Defensas evolucionadas, prueba de realidad mantenida y sólida identidad.', 'Defensas primitivas, prueba de realidad mantenida y difusión de identidad.', NULL, 'd', NULL, NULL),
  (2022, 202, NULL, '¿Cuál de las siguientes opciones NO recoge un componente del constructo “Autoritarismo de derechas” propuesto por Altemeyer?:', 'Convencionalismo.', 'Agresión autoritaria.', 'Sumisión autoritaria.', 'Liderazgo autoritario.', NULL, 'd', NULL, NULL),
  (2022, 203, NULL, 'De las siguientes afirmaciones respecto a la terapia metacognitiva de Wells, señale la INCORRECTA:', 'Es el contenido específico del pensamiento el que perpetúa el trastorno mental.', 'Considera que el distanciamiento del pensamiento no implica aceptación y eliminación del juicio.', 'Amplía el foco de las terapias cognitivas a la forma en que los individuos piensan.', 'Combina técnicas de reestructuración cognitiva, experimentos conductuales y entrenamiento atencional.', NULL, 'a', NULL, NULL),
  (2022, 204, NULL, 'En la técnica de programación de actividades para el tratamiento de la depresión de la terapia cognitiva (A. T. Beck), se le pide al paciente que registre:', 'La frecuencia de episodios de tristeza.', 'El grado de dominio y agrado.', 'La duración de los episodios de tristeza.', 'El grado de creencia en los esquemas depresógenos.', NULL, 'b', NULL, NULL),
  (2022, 205, NULL, '¿Qué afirmación es correcta en relación con la afectación del sistema atencional?:', 'El síndrome de heminegligencia por desconexión parietofrontal conserva la capacidad de atención sostenida (alerta tónica).', 'Las dificultades en atención ejecutiva en niños con autismo se han relacionado con el excesivo volumen de la región dorsolateral frontal.', 'Las personas con trastorno de hiperactividad con déficit de atención no muestran afectación en la actividad de la corteza cingulada anterior.', 'La lesión bilateral de los lóbulos parietales (síndrome de Balint) se caracteriza por ataxia visual y óptica sin que se afecte la orientación atencional.', NULL, 'b', NULL, NULL),
  (2022, 206, NULL, 'En la fobia a la sangre, inyecciones o daño:', 'Se aconseja la relajación ya que facilita la disminución de la presión sanguínea.', 'La mera exposición con prevención de respuesta es la mejor intervención.', 'La tensión aplicada es la intervención más adecuada ya que se enseña a relajar los grandes grupos musculares.', 'La técnica de tensión aplicada de Öst y Sterner se utiliza para controlar las respuestas de desmayo.', NULL, 'd', NULL, NULL),
  (2022, 207, NULL, '¿Qué tratamiento psicológico que se utiliza en el trastorno bipolar se centra en regular sus rutinas diarias?:', 'Terapia de aceptación y compromiso.', 'Terapia centrada en la compasión.', 'Terapia interpersonal y del ritmo social.', 'Terapia sistémica.', NULL, 'c', NULL, NULL),
  (2022, 208, NULL, '¿Qué afirmación es correcta con respecto a las fobias específicas?:', 'Suelen ser fenómenos transitorios.', 'La edad de inicio más frecuente es en la adolescencia entre los 12-16 años.', 'La edad de inicio más frecuente es en la infancia, entre los 7-11 años.', 'Las fobias clínicamente relevantes suelen iniciarse en la primera edad adulta (18-25 años).', NULL, 'c', NULL, NULL),
  (2022, 209, NULL, '¿Qué respuesta es correcta con relación al aprendizaje y la memoria?:', 'El lóbulo temporal medial y el hipocampo son las estructuras esenciales en el mantenimiento de contenidos en memoria a corto plazo.', 'Las regiones visuales primarias y la corteza parietal inferior son fundamentales para crear realidades que no han sido percibidas (falsos recuerdos).', 'El marcador molecular de la reconsolidación de la memoria es la disminución de la fosforilación de los receptores de glutamato GluR1.', 'La conversión de memoria a corto plazo en memoria a largo plazo es un proceso de síntesis proteica sin cambios morfológicos.', NULL, 'c', NULL, NULL),
  (2022, 210, NULL, '¿Con qué proceso están relacionados los mecanismos explicativos de la reducción del miedo durante la exposición desde un punto de vista psicofisiológico?:', 'Con la habituación.', 'Con la extinción.', 'Con la sensibilización.', 'Con la respuesta de orientación.', NULL, 'a', NULL, NULL);
